SELECT 


    o.store_id = #{q.storeId}
    AND s.platform = #{q.platform}
    AND o.status = #{q.status}
    AND o.local_status = #{q.localStatus}
    AND o.fulfillment = #{q.fulfillment}
    AND o.ship_country = #{q.country}
    AND o.order_time >= #{q.beginTime}
    AND o.order_time < #{q.endExclusive}

        AND o.ship_by < CURRENT_TIMESTAMP AND o.local_status IN ('PENDING', 'EXCEPTION', 'OUTBOUND')


        AND (o.platform_order_no LIKE CONCAT('%', #{q.keyword}, '%') OR o.buyer_name LIKE CONCAT('%', #{q.keyword}, '%')
             OR o.ship_name LIKE CONCAT('%', #{q.keyword}, '%') OR o.tracking_no LIKE CONCAT('%', #{q.keyword}, '%')
             OR EXISTS (SELECT 1 FROM ecom_order_item oi WHERE oi.order_id = o.id AND oi.seller_sku LIKE CONCAT('%', #{q.keyword}, '%')))


ORDER BY o.order_time DESC, o.id DESC

SELECT o.* FROM ecom_order o
WHERE o.store_id = #{storeId} AND o.platform_order_no IN
#{no}
